rs are supplied.\n    throw new UnsupportedOperationException(\"Implement solve\");\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","reference_solution":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nint n=in.nextInt();List<int[]>events=new ArrayList<>();for(int i=0;i<n;i++){int l=in.nextInt(),r=in.nextInt(),h=in.nextInt();events.add(new int[]{l,h,1});events.add(new int[]{r,h,-1});}events.sort(Comparator.comparingInt(x->x[0]));TreeMap<Integer,Integer>active=new TreeMap<>();active.put(0,1);List<String>b=new ArrayList<>();int prev=0;for(int i=0;i<events.size();){int x=events.get(i)[0];while(i<events.size()&&events.get(i)[0]==x){int[]e=events.get(i++);int count=active.getOrDefault(e[1],0)+e[2];if(count==0)active.remove(e[1]);else active.put(e[1],count);}int h=active.lastKey();if(h!=prev){b.add(x+\" \"+h);prev=h;}}return String.join(\"\\n\",b);\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"5\n2 9 10\n3 7 15\n5 12 12\n15 20 10\n19 24 8\n","expected_output":"2 10\n3 15\n7 12\n12 0\n15 10\n20 8\n24 0","is_sample":true},{"ordinal":2,"stdin":"2\n0 2 3\n2 5 3\n","expected_output":"0 3\n5 0","is_sample":true},{"ordinal":3,"stdin":"1\n0 1 1\n","expected_output":"0 1\n1 0","is_sample":false},{"ordinal":4,"stdin":"2\n1 3 2\n1 3 5\n","expected_output":"1 5\n3 0","is_sample":false},{"ordinal":5,"stdin":"2\n1 10 3\n2 3 8\n","expected_output":"1 3\n2 8\n3 3\n10 0","is_sample":false},{"ordinal":6,"stdin":"5\n0 2 1\n3 5 2\n6 8 3\n9 11 4\n12 14 5\n","expected_output":"0 1\n2 0\n3 2\n5 0\n6 3\n8 0\n9 4\n11 0\n12 5\n14 0","is_sample":false},{"ordinal":7,"stdin":"3\n0 5 1\n1 4 2\n2 3 3\n","expected_output":"0 1\n1 2\n2 3\n3 2\n4 1\n5 0","is_sample":false},{"ordinal":8,"stdin":"3\n0 3 3\n1 4 3\n2 5 3\n","expected_output":"0 3\n5 0","is_sample":false},{"ordinal":9,"stdin":"7\n0 4 2\n1 5 3\n2 6 4\n3 7 2\n4 8 3\n5 9 4\n6 10 2\n","expected_output":"0 2\n1 3\n2 4\n9 2\n10 0","is_sample":false},{"ordinal":10,"stdin":"3\n0 100 1\n20 40 5\n60 80 4\n","expected_output":"0 1\n20 5\n40 1\n60 4\n80 1\n100 0","is_sample":false}]},{"slug":"burst-balloons-reward","title":"Burst Balloons Reward","prompt