ring();\n  }\n  static String solve(FastScanner in) throws Exception {\n    // Read the documented input using in.nextInt(), in.nextLong(), or in.next().\n    // Return the requested output. Only input/output helpers are supplied.\n    throw new UnsupportedOperationException(\"Implement solve\");\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","reference_solution":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nint n=in.nextInt();int[] a=array(in,n);int[] b=new int[n+2];b[0]=b[n+1]=1;System.arraycopy(a,0,b,1,n);long[][]d=new long[n+2][n+2];for(int len=1;len<=n;len++)for(int l=1;l+len-1<=n;l++){int r=l+len-1;for(int k=l;k<=r;k++)d[l][r]=Math.max(d[l][r],d[l][k-1]+d[k+1][r]+(long)b[l-1]*b[k]*b[r+1]);}return \"\"+d[1][n];\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"4\n3 1 5 8\n","expected_output":"167","is_sample":true},{"ordinal":2,"stdin":"2\n1 5\n","expected_output":"10","is_sample":true},{"ordinal":3,"stdin":"1\n0\n","expected_output":"0","is_sample":false},{"ordinal":4,"stdin":"1\n7\n","expected_output":"7","is_sample":false},{"ordinal":5,"stdin":"3\n0 0 0\n","expected_output":"0","is_sample":false},{"ordinal":6,"stdin":"4\n1 1 1 1\n","expected_output":"4","is_sample":false},{"ordinal":7,"stdin":"3\n2 4 3\n","expected_output":"33","is_sample":false},{"ordinal":8,"stdin":"3\n9 1 9\n","expected_output":"171","is_sample":false},{"ordinal":9,"stdin":"5\n1 2 3 4 5\n","expected_output":"110","is_sample":false},{"ordinal":10,"stdin":"6\n5 2 6 1 3 4\n","expected_output":"295","is_sample":false}]},{"slug":"cancel-adjacent-pairs","title":"Cancel Adjacent Pairs","prompt":"Repeatedly remove the leftmost adjacent pair of equal characters until no pair remains. Print the remaining string, or EMPTY.\n\nInput\nOne nonempty lowercase ASCII string s, of length at most 1000.\n\nRead standard input and print only the requested result. Array indices are zero-based. Use 64-bit integers for sums and counts unless stated otherwise.\n\nExample 1\nInput:\nabacaba\nOutput:\nabacaba\n\nExample 2\nInput:\naaaa\nOutput:\nEMPTY","difficulty":5,"starter_code":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String solve(FastScanner in) throws Exception {\n    // Read the documented input using in.nextInt(), in.nextLong(), or in.next().\n    // Return the requested output. Only input/output helpers are supplied.\n    throw new UnsupportedOperationException(\"Implement solve\");\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","reference_solution":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nString s=in.next();int n=s.length();StringBuilder b=new StringBuilder();for(char c:s.toCharArray()){int k=b.length();if(k>0&&b.charAt(k-1)==c)b.deleteCharAt(k-1);else b.append(c);}return b.length()==0?\"EMPTY\":b.toString();\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"abacaba\n","expected_output":"abacaba","is_sample":true},{"ordinal":2,"stdin":"aaaa\n","expected_output":"EMPTY","is_sample":true},{"ordinal":3,"stdin":"z\n","expected_output":"z","is_sample":false},{"ordinal":4,"stdin":"ab\n","expected_output":"ab","is_sample":false},{"ordinal":5,"stdin":"abcabcbb\n","expected_output":"abcabc","is_sample":false},{"ordinal":6,"stdin":"pwwkew\n","expected_output":"pkew","is_sample":false},{"ordinal":7,"stdin":"banana\n","expected_output":"banana","is_sample":false},{"ordinal":8,"stdin":"mississippi\n","expected_output":"m","is_sample":false},{"ordinal":9,"stdin":"abcdefghijklmnopqrstuvwxyz\n","expected_output":"abcdefghijklmnopqrstuvwxyz","is_sample":false},{"ordinal":10,"stdin":"aabbccddeeffggabacabadabacaba\n","expected_output":"abacabadabacaba","is_sample":false}]},{"slug":"circular-fuel-route","title":"Circular Fuel Route","prompt":"Stations form a circle. At each station collect gas then spend cost to reach the next. Start with an empty tank of unlimited capacity. Print the smallest starting index that completes one circuit, or -1.\n\nInput\nn, then n lines gas cost. 1 <= n <= 2000; 0 <= gas,cost <= 1000000.\n\nRead standard input and print only the requested result. Array indices are zero-based. Use 64-bit integers for sums and counts unless stated otherwise.\n\nExample 1\nInput:\n5\n1 3\n2 4\n3 5\n4 1\n5 2\nOutput:\n3\n\nExample 2\nInput:\n3\n2 3\n3 4\n4 3\nOutput:\n-1","difficulty":6,"starter_code":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String solve(FastScanner in) throws Exception {\n    // Read the documented input using in.nextInt(), in.nextLong(), or in.next().\n    // Return the requested output. Only input/output helpers are supplied.\n    throw new UnsupportedOperationException(\"Implement solve\");\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","reference_solution":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      