;\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nint n=in.nextInt();int[][]a=new int[n][2];for(int[]r:a){r[0]=in.nextInt();r[1]=in.nextInt();}long best=Long.MAX_VALUE;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){long x=(long)a[i][0]-a[j][0],y=(long)a[i][1]-a[j][1];best=Math.min(best,x*x+y*y);}return \"\"+best;\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"5\n0 0\n2 0\n2 2\n0 2\n1 1\n","expected_output":"2","is_sample":true},{"ordinal":2,"stdin":"3\n0 0\n1 1\n2 2\n","expected_output":"2","is_sample":true},{"ordinal":3,"stdin":"2\n0 0\n3 4\n","expected_output":"25","is_sample":false},{"ordinal":4,"stdin":"2\n2 3\n5 7\n","expected_output":"25","is_sample":false},{"ordinal":5,"stdin":"3\n0 0\n1 0\n0 1\n","expected_output":"1","is_sample":false},{"ordinal":6,"stdin":"3\n0 0\n0 0\n1 1\n","expected_output":"0","is_sample":false},{"ordinal":7,"stdin":"6\n0 0\n1 1\n2 4\n3 9\n4 16\n5 25\n","expected_output":"2","is_sample":false},{"ordinal":8,"stdin":"9\n0 0\n1 0\n2 0\n0 1\n1 1\n2 1\n0 2\n1 2\n2 2\n","expected_output":"1","is_sample":false},{"ordinal":9,"stdin":"5\n-3 -2\n-1 5\n4 4\n5 -1\n0 0\n","expected_output":"13","is_sample":false},{"ordinal":10,"stdin":"20\n4 -7\n-12 -15\n-17 6\n-5 11\n-5 14\n19 14\n16 3\n0 -8\n-6 2\n9 5\n16 -11\n8 17\n10 -11\n-4 9\n-14 -19\n-7 17\n3 10\n13 -5\n-9 -12\n-18 -3\n","expected_output":"5","is_sample":false}]},{"slug":"coin-combination-count","title":"Co