nputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nint n=in.nextInt();int[][]a=new int[n][2];for(int[]r:a){r[0]=in.nextInt();r[1]=in.nextInt();}Arrays.sort(a,(x,y)->x[0]==y[0]?Integer.compare(x[1],y[1]):Integer.compare(x[0],y[0]));List<int[]>hull=new ArrayList<>();for(int pass=0;pass<2;pass++){int base=hull.size();for(int index=0;index<n;index++){int[]p=a[pass==0?index:n-1-index];while(hull.size()>=base+2){int[]u=hull.get(hull.size()-2),v=hull.get(hull.size()-1);long cross=(long)(v[0]-u[0])*(p[1]-u[1])-(long)(v[1]-u[1])*(p[0]-u[0]);if(cross>0)break;hull.remove(hull.size()-1);}hull.add(p);}hull.remove(hull.size()-1);}long area=0;for(int i=0;i<hull.size();i++){int[]u=hull.get(i),v=hull.get((i+1)%hull.size());area+=(long)u[0]*v[1]-(long)u[1]*v[0];}return \"\"+Math.abs(area);\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"5\n0 0\n2 0\n2 2\n0 2\n1 1\n","expected_output":"8","is_sample":true},{"ordinal":2,"stdin":"3\n0 0\n1 1\n2 2\n","expected_output":"0","is_sample":true},{"ordinal":3,"stdin":"1\n0 0\n","expected_output":"0","is_sample":false},{"ordinal":4,"stdin":"2\n2 3\n5 7\n","expected_output":"0","is_sample":false},{"ordinal":5,"stdin":"3\n0 0\n1 0\n0 1\n","expected_output":"1","is_sample":false},{"ordinal":6,"stdin":"3\n0 0\n0 0\n1 1\n","expected_output":"0","is_sample":false},{"ordinal":7,"stdin":"6\n0 0\n1 1\n2 4\n3 9\n4 16\n5 25\n","expected_output":"40","is_sample":false},{"ordinal":8,"stdin":"9\n0 0\n1 0\n2 0\n0 1\n1 1\n2 1\n0 2\n1 2\n2 2\n","expected_output":"8","is_sample":false},{"ordinal":9,"stdin":"5\n-3 -2\n-1 5\n4 4\n5 -1\n0 0\n","expected_output":"78","is_sample":false},{"ordinal":10,"stdin":"20\n4 -7\n-12 -15\n-17 6\n-5 11\n-5 14\n19 14\n16 3\n0 -8\n-6 2\n9 5\n16 -11\n8 17\n10 -11\n-4 9\n-14 -19\n-7 17\n3 10\n13 -5\n-9 -12\n-18 -3\n","expected_output":"2063","is_sample":false}]},{"slug":"count-array-inversions","title":"Count Array Inversions","prompt":"Count pairs i < j for which a[i] > a[j]. Equal values are not inversions.\n\nInput\nAn integer n (1 <= n <= 2000), then n integers a[i] (-1000000 <= a[i] <= 1000000).\n\nRead standard input and print only the requested result. Array indices are zero-based. Use 64-bit integers for sums and counts unless stated otherwise.\n\nExample 1\nInput:\n5\n3 1 4 1 5\nOutput:\n3\n\nExample 2\nInput:\n3\n2 2 2\nOutput:\n0","difficulty":7,