;\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nString a=in.next(),b=in.next(),s=in.next();int n=a.length(),m=b.length();if(s.length()!=n+m)return \"false\";boolean[][]d=new boolean[n+1][m+1];d[0][0]=true;for(int i=0;i<=n;i++)for(int j=0;j<=m;j++){if(i>0)d[i][j]|=d[i-1][j]&&a.charAt(i-1)==s.charAt(i+j-1);if(j>0)d[i][j]|=d[i][j-1]&&b.charAt(j-1)==s.charAt(i+j-1);}return \"\"+d[n][m];\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"aabcc\ndbbca\naadbbcbcac\n","expected_output":"true","is_sample":true},{"ordinal":2,"stdin":"aabcc\ndbbca\naadbbbaccc\n","expected_output":"false","is_sample":true},{"ordinal":3,"stdin":"a\nb\nab\n","expected_output":"true","is_sample":false},{"ordinal":4,"stdin":"a\nb\nba\n","expected_output":"true","is_sample":false},{"ordinal":5,"stdin":"a\na\naa\n","expected_output":"true","is_sample":false},{"ordinal":6,"stdin":"ab\ncd\nacbd\n","expected_output":"true","is_sample":false},{"ordinal":7,"stdin":"ab\ncd\nadbc\n","expected_output":"false","is_sample":false},{"ordinal":8,"stdin":"abc\nxyz\naxbycz\n","expected_output":"true","is_sample":false},{"ordinal":9,"stdin":"abc\nxyz\nabcxyz\n","expected_output":"true","is_sample":false},{"ordinal":10,"stdin":"aaab\naaba\naaaaabba\n","expected_