ew int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nint h=in.nextInt(),w=in.nextInt();int[][]a=new int[h][w];for(int i=0;i<h;i++)for(int j=0;j<w;j++)a[i][j]=in.nextInt();int[]dr={-1,0,1,0},dc={0,1,0,-1};boolean[][]seen=new boolean[h][w];List<List<int[]>>groups=new ArrayList<>();for(int i=0;i<h;i++)for(int j=0;j<w;j++)if(a[i][j]==1&&!seen[i][j]){List<int[]>g=new ArrayList<>();Deque<int[]>q=new ArrayDeque<>();q.add(new int[]{i,j});seen[i][j]=true;while(!q.isEmpty()){int[]u=q.remove();g.add(u);for(int k=0;k<4;k++){int r=u[0]+dr[k],c=u[1]+dc[k];if(r>=0&&r<h&&c>=0&&c<w&&a[r][c]==1&&!seen[r][c]){seen[r][c]=true;q.add(new int[]{r,c});}}}groups.add(g);}int best=0;for(List<int[]>g:groups)best=Math.max(best,g.size());return \"\"+best;\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"2 3\n1 1 0\n0 1 1\n","expected_output":"4","is_sample":true},{"ordinal":2,"stdin":"3 3\n1 0 1\n0 1 0\n1 0 1\n","expected_output":"1","is_sample":true},{"ordinal":3,"stdin":"1 1\n0\n","expected_output":"0","is_sample":false},{"ordinal":4,"stdin":"1 1\n1\n","expected_output":"1","is_sample":false},{"ordinal":5,"s