ws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String solve(FastScanner in) throws Exception {\n    // Read the documented input using in.nextInt(), in.nextLong(), or in.next().\n    // Return the requested output. Only input/output helpers are supplied.\n    throw new UnsupportedOperationException(\"Implement solve\");\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","reference_solution":"\nimport java.io.*;\nimport java.util.*;\npublic class Main {\n  static final long MOD = 1000000007L;\n  static class FastScanner {\n    private final InputStream in = System.in;\n    private final byte[] buffer = new byte[65536];\n    private int pos, len;\n    int read() throws IOException {\n      if(pos >= len) { len=in.read(buffer); pos=0; if(len<0) return -1; }\n      return buffer[pos++];\n    }\n    String next() throws IOException {\n      StringBuilder b=new StringBuilder(); int c;\n      do { c=read(); } while(c<=32 && c!=-1);\n      if(c==-1) throw new EOFException();\n      while(c>32 && c!=-1) { b.append((char)c); c=read(); }\n      return b.toString();\n    }\n    int nextInt() throws IOException { return Integer.parseInt(next()); }\n    long nextLong() throws IOException { return Long.parseLong(next()); }\n  }\n  static int[] array(FastScanner in, int n) throws Exception {\n    int[] a=new int[n]; for(int i=0;i<n;i++) a[i]=in.nextInt(); return a;\n  }\n  static String join(int[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(int x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(long[] a) {\n    if(a.length==0) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(long x:a) j.add(\"\"+x); return j.toString();\n  }\n  static String join(Collection<?> a) {\n    if(a.isEmpty()) return \"EMPTY\";\n    StringJoiner j=new StringJoiner(\" \"); for(Object x:a) j.add(\"\"+x); return j.toString();\n  }\n  static long gcd(long a,long b) { while(b!=0){long t=a%b;a=b;b=t;} return Math.abs(a); }\n  static long power(long a,long b,long m) {long r=1%m;while(b>0){if((b&1)==1)r=r*a%m;a=a*a%m;b>>=1;}return r;}\n  static String solve(FastScanner in) throws Exception {\nint n=in.nextInt(),k=in.nextInt();long[] d=new long[k+1];for(int i=0;i<n;i++){int w=in.nextInt(),v=in.nextInt();for(int j=k;j>=w;j--)d[j]=Math.max(d[j],d[j-w]+v);}return \"\"+d[k];\n  }\n  public static void main(String[] args) throws Exception { System.out.println(solve(new FastScanner())); }\n}\n","cases":[{"ordinal":1,"stdin":"3 5\n2 3\n3 4\n4 5\n","expected_output":"7","is_sample":true},{"ordinal":2,"stdin":"1 4\n5 10\n","expected_output":"0","is_sample":true},{"ordinal":3,"stdin":"1 1\n1 7\n","expected_output":"7","is_sample":false},{"ordinal":4,"stdin":"2 1\n1 2\n1 3\n","expected_output":"3","is_sample":false},{"ordinal":5,"stdin":"2 0\n3 9\n4 10\n","expected_output":"0","is_sample":false},{"ordinal":6,"stdin":"2 8\n2 0\n3 0\n","expected_output":"0","is_sample":false},{"ordinal":7,"stdin":"3 4\n2 4\n2 5\n2 6\n","expected_output":"11","is_sample":false},{"ordinal":8,"stdin":"3 6\n5 20\n4 15\n1 3\n","expected_output":"23","is_sample":false},{"ordinal":9,"stdin":"12 13\n1 0\n2 3\n3 6\n4 9\n5 12\n1 15\n2 1\n3 4\n4 7\n5 10\n1 13\n2 16\n","expected_output":"65","is_sample":false},{"ordinal":10,"stdin":"15 30\n1 0\n2 7\n3 14\n4 21\n5 5\n6 12\n7 19\n1 3\n2 10\n3 17\n4 1\n5 8\n6 15\n7 22\n1 6\n","expected_output":"119","is_sample":false}]}]$bank200$::jsonb) AS q(
  slug text, title text, prompt text, difficulty integer, starter_code text,
  reference_solution text, cases jsonb
);
DO $guard$ BEGIN
  IF (SELECT count(*) FROM bank200_question) <> 180 THEN RAISE EXCEPTION 'Expected 180 additions'; END IF;
  IF (SELECT array_agg(slug::text ORDER BY slug) FROM challenge_platform.question
      WHERE is_active AND slug NOT IN (SELECT slug FROM bank200_question))
      IS DISTINCT FROM ARRAY['coin-change','container-with-most-water','course-schedule','decode-ways','edit-distance','jump-game','kth-largest-element','largest-rectangle-histogram','longest-increasing-subsequence','longest-palindromic-substring','maximum-circular-subarray','median-two-sorted-arrays','merge-intervals','minimum-window-substring','number-of-islands','search-rotated-sorted-array','sliding-window-maximum','subarray-sum-equals-k','trapping-rain-water','word-break']::text[] THEN
    RAISE EXCEPTION 'Active baseline differs from the expected original 20 questions; review before applying';
  END IF;
END $guard$;
INSERT INTO challenge_platform.question
  (slug,title,prompt,difficulty,language,judge_language_id,starter_code,reference_solution,time_limit_seconds,max_score,is_active)
SELECT slug,title,prompt,difficulty,'Java',62,starter_code,reference_solution,600,100,false
FROM bank200_question ORDER BY slug
ON CONFLICT (slug) DO NOTHING;
DO $guard$ BEGIN
  IF EXISTS (SELECT 1 FROM bank200_question b JOIN challenge_platform.question q USING(slug)
    WHERE (q.title,q.prompt,q.difficulty,q.language,q.judge_language_id,q.starter_code,q.reference_solution,q.time_limit_seconds,q.max_score)
      IS DISTINCT FROM (b.title,b.prompt,b.difficulty,'Java',62,b.starter_code,b.reference_solution,600,100::numeric)) THEN
    RAISE EXCEPTION 'A new-bank slug already exists with different content; no existing question was overwritten';
  END IF;
END $guard$;
CREATE TEMP TABLE bank200_case ON COMMIT DROP AS
SELECT q.id AS question_id, c.ordinal, c.stdin, c.expected_output, c.is_sample
FROM bank200_question b JOIN challenge_platform.question q USING(slug)
CROSS JOIN LATERAL jsonb_to_recordset(b.cases) AS c(ordinal integer, stdin text, expected_output text, is_sample boolean);
INSERT INTO challenge_platform.question_testcase (question_id,ordinal,stdin,expected_output,is_sample,points)
SELECT question_id,ordinal,stdin,expected_output,is_sample,10 FROM bank200_case ORDER BY question_id,ordinal
ON CONFLICT (question_id,ordinal) DO NOTHING;
DO $guard$ BEGIN
  IF EXISTS (SELECT 1 FROM bank200_case b JOIN challenge_platform.question_testcase c USING(question_id,ordinal)
    WHERE (c.stdin,c.expected_output,c.is_sample,c.points) IS DISTINCT FROM (b.stdin,b.expected_output,b.is_sample,10::numeric))
    OR (SELECT count(*) FROM challenge_platform.question_testcase WHERE question_id IN (SELECT question_id FROM bank200_case)) <> 1800 THEN
    RAISE EXCEPTION 'Testcase content/count differs; no existing testcase was overwritten';
  END IF;
END $guard$;
UPDATE challenge_platform.question SET is_active=true
WHERE slug IN (SELECT slug FROM bank200_question) AND NOT is_active;
DO $guard$ BEGIN
  IF (SELECT count(*) FROM challenge_platform.question WHERE is_active) <> 200 THEN RAISE EXCEPTION 'Expected 200 active questions'; END IF;
  IF EXISTS (SELECT 1 FROM challenge_platform.question q
    LEFT JOIN challenge_platform.question_testcase c ON c.question_id=q.id
    WHERE q.is_active GROUP BY q.id HAVING count(c.id)<>10 OR count(c.id) FILTER(WHERE c.is_sample)<>2 OR sum(c.points)<>100) THEN
    RAISE EXCEPTION 'Every active question must have ten testcases, two samples, and 100 total points';
  END IF;
END $guard$;
COMMIT;
